// Transformar las filas de Google Sheets a products.ts
const items = $input.all();

const rawProducts = items.map(item => {
  const row = item.json;
  const images = [];
  if (row.foto_1) images.push(row.foto_1.trim());
  if (row.foto_2) images.push(row.foto_2.trim());
  if (images.length === 0) images.push('/images/products/placeholder.png');

  const stockQty = parseInt(row.stock || '0', 10);
  const inStock = row.en_stock === true || row.en_stock === 'TRUE' || stockQty > 0;

  return {
    id: row.id || `DYNE_${(row.categoria || 'GENERIC').toUpperCase()}_${Math.floor(Math.random() * 1000)}`,
    slug: row.slug || (row.nombre || 'producto').toLowerCase().replace(/[^a-z0-9]+/g, '-'),
    name: row.nombre || 'Producto sin nombre',
    description: row.descripcion || '',
    price: parseFloat(row.precio || 0),
    compareAtPrice: row.precio_anterior ? parseFloat(row.precio_anterior) : undefined,
    category: (row.categoria || 'audio').toLowerCase(),
    images: images,
    variants: [
      { size: row.talle || 'U', inStock: inStock, stock: stockQty }
    ],
    badge: row.badge || undefined,
    featured: row.destacado === true || row.destacado === 'TRUE',
    createdAt: new Date().toISOString()
  };
});

const productsTsContent = `import { Product, ProductVariant } from '@/types/product';

const defaultVariants: ProductVariant[] = [
  { size: 'U', inStock: true, stock: 10 }
];

const RAW_PRODUCTS: Product[] = ${JSON.stringify(rawProducts, (key, value) => value === undefined ? null : value, 2)};

const basePath = process.env.NEXT_PUBLIC_BASE_PATH || '';

export const products: Product[] = RAW_PRODUCTS.map(p => ({
  ...p,
  images: p.images.map(img => img.startsWith('http') ? img : \`\${basePath}\${img}\`)
}));

export function getProductBySlug(slug: string): Product | undefined {
  return products.find(p => p.slug === slug);
}

export function getProductsByCategory(category: string): Product[] {
  if (category === 'all') return products;
  return products.filter(p => p.category === category);
}
`;

const base64Content = Buffer.from(productsTsContent, 'utf-8').toString('base64');

return [{ json: { content_base64: base64Content } }];

